// normalise\n	float atten;\n	if (posrange.w == 0.0)		// the w component of posrange is 0 if the point light is disabled - if we don't catch it here we might end up generating INFs or NaNs\n	{\n		atten = 0.0;\n	}\n	else\n	{\n#ifdef MIRROR_WIN32_LIGHTING_EQUATION\n	// This is based on the Win32 D3D and OpenGL falloff model, where:\n	// Attenuation = 1.0f / (factor0 + (d * factor1) + (d*d * factor2))\n	// For some reason, factor0 is set to 0.0f while factor1 is set to 1.0f/lightrange (on both D3D and OpenGL)\n	// This'll result in no visible falloff as 1.0f / (d / lightrange) will always be larger than 1.0f (if the vertex is within range)\n	\n		atten = 1.0 / (veclen / posrange.w);\n		if (veclen > posrange.w)\n		{\n			atten = 0.0;\n		}	\n#else\n		atten = clamp( (1.0 - (veclen / posrange.w)), 0.0, 1.0);		// storing 1.0f/range instead would save a rcp\n#endif\n	}\n	float dotresult = dot(ws_normal, diffvec);\n	dotresult = max(0.0, dotresult);\n\n	return dotresult * atten * diffusecol;\n}\n\nvec4 DoLighting(vec4 vertexcolour, vec4 objectspacepos, vec3 objectspacenormal)\n{\n	if (gm_LightingEnabled)\n	{\n		// Normally we'd have the light positions\\directions back-transformed from world to object space\n		// But to keep things simple for the moment we'll just transform the normal to world space\n		vec4 objectspacenormal4 = vec4(objectspacenormal, 0.0);\n		vec3 ws_normal;\n		ws_normal = (gm_Matrices[MATRIX_WORLD] * objectspacenormal4).xyz;\n		ws_normal = normalize(ws_normal);\n\n		vec3 ws_pos;\n		ws_pos = (gm_Matrices[MATRIX_WORLD] * objectspacepos).xyz;\n\n		// Accumulate lighting from different light types\n		vec4 accumcol = vec4(0.0, 0.0, 0.0, 0.0);		\n		for(int i = 0; i < MAX_VS_LIGHTS; i++)\n		{\n			accumcol += DoDirLight(ws_normal, gm_Lights_Direction[i], gm_Lights_Colour[i]);\n		}\n\n		for(int i = 0; i < MAX_VS_LIGHTS; i++)\n		{\n			accumcol += DoPointLight(ws_pos, ws_normal, gm_Lights_PosRange[i], gm_Lights_Colour[i]);\n		}\n\n		accumcol *= vertexcolour;\n		accumcol += gm_AmbientColour;\n		accumcol = min(vec4(1.0, 1.0, 1.0, 1.0), accumcol);\n		accumcol.a = vertexcolour.a;\n		return accumcol;\n	}\n	else\n	{\n		return vertexcolour;\n	}\n}\n\n#define _YY_GLSLES_ 1\n/*\n	'Vignette' by Xor\n	\n	A generic vertex passthrough shader.\n*/\nattribute vec3 in_Position;\nattribute vec4 in_Colour;\nattribute vec2 in_TextureCoord;\n\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nvoid main()\n{\n    gl_Position = gm_Matrices[MATRIX_WORLD_VIEW_PROJECTION] * vec4(in_Position.xy, 0.0, 1.0);\n    \n    v_vColour = in_Colour;\n    v_vTexcoord = in_TextureCoord;\n}\n",
_84:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n/*\n	'Vignette' by Xor\n	\n	Adds a smooth vignette border to the screen.\n	There are parameters to adjust the fade and shape.\n	The texture determines the color and alpha!\n*/\n\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\n//Surface resolution for pixel calculations\nuniform vec2 gm_pSurfaceDimensions;\n\n//Vignette start and end points (0.0 = screen center, 1.0 = screen side)\nuniform vec2 g_VignetteEdges;\n//Vignette corner sharpness (1.0 = circular, higher = more square)\nuniform float g_VignetteSharpness;\n\n//Vignette texture for color or texturing\nuniform sampler2D g_VignetteTexture;\n//Vignette texture texel size for 1 to 1 scaling\nuniform vec2 g_VignetteTextureTexelSize;\n\nvoid main()\n{\n	//Sample base texture for blending with\n	vec4 colour = v_vColour * texture2D(gm_BaseTexture, v_vTexcoord);\n	\n	\n	//Distance to screen center (from 0.0 to 1.0)\n	vec2 center = abs(v_vTexcoord - 0.5) * 2.0;\n	//Compute exponential coordinates\n	vec2 coord = pow(center, vec2(g_VignetteSharpness));\n	//Get linear distance to edge\n	float vignette = pow(length(coord), 1.0 / g_VignetteSharpness);\n	//Normalize to vignette edges (positive uncapped)\n	vignette = max((vignette-g_VignetteEdges.x) / (g_VignetteEdges.y-g_VignetteEdges.x), 0.0);\n	\n	//Compute pixel coordinates (screen-space)\n	vec2 pixel = v_vTexcoord * gm_pSurfaceDimensions;\n	//Convert to vignette texture coordinates\n	vec2 vignette_coord = pixel * g_VignetteTextureTexelSize;\n	//Sample vignette texture\n	vec4 vignette_sample = texture2D(g_VignetteTexture, vignette_coord);\n	\n	//Blend with base color	\n	colour.rgb = mix(colour.rgb, vignette_sample.rgb, min(vignette * vignette_sample.a, 1.0));\n	gl_FragColor = v_vColour * colour;\n}\n",
